# Set up the environment and start the application
Application.put_env(:ash, :validate_domain_resource_inclusion?, false)
Application.put_env(:ash, :validate_domain_config_inclusion?, false)

# Seed the ETS database
Tracker.Delivery.Seed.seed!()

# Helper to run GQL documents
defmodule GqlRunner do
  def run(query, opts \\ []) do
    case Absinthe.run(query, Tracker.GraphqlSchema, opts) do
      {:ok, result} ->
        IO.puts("=== SUCCESS ===")
        IO.puts(Jason.encode!(result, pretty: true))
        result
      {:error, reason} ->
        IO.puts("=== ERROR ===")
        IO.inspect(reason)
        reason
    end
  end
end

